/// Per-potion dispatch coverage: every one of the 63 ported
/// `PotionKind`s resolves through the registry to
/// `EffectResult::Resolved` (i.e. is no longer `NotImplemented`).
/// Macro-style coverage is folded into a single iterator test
/// because the workspace has no `paste` dependency; the test
/// still asserts per-variant and panics with the offending kind
/// name on failure.
#[test]
fn every_potion_kind_dispatches_to_resolved() {
    ensure_installed();
    for &k in &PotionKind::ALL {
        let mut state = CombatState::default();
        assert_eq!(
            dispatch(&mut state, k, None),
            EffectResult::Resolved,
            "{k:?} ({}) failed to dispatch",
            k.python_name(),
        );
    }
}

/// Bead `sts2-rs-ybtmu`: `install_default_registry` publishes the
/// canonical `PotionKind → PotionTargetType` mapping into core so
/// `SurroundedPower.BeforePotionUsed` can decide whether a potion-drink
/// re-faces the surrounded player. The lookup must agree with
/// `all::spec_for` for every kind, and the load-bearing distinction is
/// `AnyEnemy` (VulnerablePotion flips facing) vs everything else
/// (FlexPotion = `AnyPlayer`, does not).
#[test]
fn potion_target_types_registered_into_core() {
    use sts2_core::potion_effects::lookup_target_type;
    use sts2_core::potions::PotionTargetType;
    ensure_installed();
    for &k in &PotionKind::ALL {
        assert_eq!(
            lookup_target_type(k),
            Some(crate::potions::all::spec_for(k).target_type),
            "{k:?} target-type missing/mismatched in core registry",
        );
    }
    assert_eq!(
        lookup_target_type(PotionKind::VulnerablePotion),
        Some(PotionTargetType::AnyEnemy),
        "VulnerablePotion is the AnyEnemy potion that flips Surrounded facing",
    );
    assert_eq!(
        lookup_target_type(PotionKind::FlexPotion),
        Some(PotionTargetType::AnyPlayer),
        "FlexPotion targets a player and must NOT flip Surrounded facing",
    );
}

/// `legal_actions` rejects character-locked potions (Defect's
/// `FocusPotion` held by an Ironclad).
#[test]
fn drink_potion_rejected_for_wrong_character() {
    ensure_installed();
    let mut state = CombatState {
        phase: CombatPhase::PlayerPlayPhase,
        ..CombatState::default()
    };
    state.player.character = Some(CharacterId::Ironclad);
    state.player.potions.push(PotionKind::FocusPotion);
    state.player.potions.push(PotionKind::CunningPotion);
    let acts = sts2_core::legal_actions(&state);
    let drinkable = acts
        .iter()
        .filter(|a| matches!(a, sts2_core::Action::DrinkPotion { .. }))
        .count();
    assert_eq!(
        drinkable, 0,
        "Defect/Silent-locked potions must not be drinkable by Ironclad",
    );
}

/// Conversely, a Defect player can drink `FocusPotion` but not
/// Silent's `CunningPotion`.
#[test]
fn drink_potion_accepted_for_matching_character() {
    ensure_installed();
    let mut state = CombatState {
        phase: CombatPhase::PlayerPlayPhase,
        ..CombatState::default()
    };
    state.player.character = Some(CharacterId::Defect);
    state.player.potions.push(PotionKind::FocusPotion); // OK
    state.player.potions.push(PotionKind::CunningPotion); // blocked
    state.player.potions.push(PotionKind::BlockPotion); // OK (unlocked)
    let acts = sts2_core::legal_actions(&state);
    let slots: Vec<u8> = acts
        .iter()
        .filter_map(|a| match a {
            sts2_core::Action::DrinkPotion { potion_slot, .. } => Some(*potion_slot),
            _ => None,
        })
        .collect();
    assert_eq!(slots, vec![0, 2]);
}

