fn fresh_state_with_player(hp: i32, max_hp: i32) -> CombatState {
    use smallvec::SmallVec;
    use sts2_core::{Creature, CreatureUid, IntentHistory, MonsterId, MonsterKind};
    let mut state = CombatState::default();
    let uid = CreatureUid::new(1).expect("non-zero uid");
    state.creatures.push(Creature {
        id: uid.0,
        current_hp: hp,
        max_hp,
        block: 0,
        powers: SmallVec::new(),
        // Sentinel; the player-Creature has no real species. Tests
        // only read hp / max_hp / block from this row.
        species: Some(MonsterKind::Nibbit),
        monster_id: MonsterId(""),
        intent: None,
        intent_history: IntentHistory::default(),
        ai: None,
    });
    state.player.creature_uid = Some(uid);
    state.player.current_hp = hp;
    state.player.max_hp = max_hp;
    state
}

