/// Bead `sts2-rs-3unld`: SpeedPotion folds +5 Dexterity into the
/// player's visible DexterityPower and registers SpeedPotion(5)
/// for the turn-end revert (mirrors `drink_flex_potion`/Strength).
/// The earlier port only stamped the SpeedPotion counter — no
/// Dexterity was applied and no listener consumed it, so the
/// potion silently did nothing.
#[test]
fn speed_potion_grants_dexterity_and_marker() {
    use sts2_core::powers::PowerKind;
    ensure_installed();
    let mut state = fresh_state_with_player(50, 80);
    assert_eq!(
        dispatch(&mut state, PotionKind::SpeedPotion, None),
        EffectResult::Resolved
    );
    let dex = state
        .powers
        .iter()
        .find(|p| p.kind == PowerKind::Dexterity)
        .map_or(0, |p| p.amount);
    assert_eq!(dex, 5, "Dexterity +5 applied on drink");
    let marker = state
        .powers
        .iter()
        .find(|p| p.kind == PowerKind::SpeedPotion)
        .map_or(0, |p| p.amount);
    assert_eq!(
        marker, 5,
        "SpeedPotion(5) counter retained for turn-end revert"
    );
}

/// Bead `sts2-rs-38pae`: C# BlockPotion is `BlockVar(12m, Unpowered)`
/// so Frail / Dexterity must NOT fold into the grant. The prior
/// `gain_block_player` route passed `ValueProps::MOVE` which made
/// Frail multiply the 12 down to 9 — observable divergence vs C#.
/// Bead `sts2-rs-7iag9`: C# Fortifier adds `target.Block * 2`
/// Unpowered → end-state is 3×starting-block, NOT 2×. Python pin
/// (`t.gain_block(t.block)`) drifted; C# is source of truth.
#[test]
fn fortifier_triples_block_per_csharp_block_times_two() {
    ensure_installed();
    let mut state = fresh_state_with_player(50, 80);
    state.player.block = 10;
    assert_eq!(
        dispatch(&mut state, PotionKind::Fortifier, None),
        EffectResult::Resolved
    );
    assert_eq!(
        state.player.block, 30,
        "Fortifier adds 2×B (=20) on top of starting 10 → 30, not 20"
    );
}

/// Bead `sts2-rs-7iag9`: Frail must NOT fold into the Fortifier
/// grant (C# uses ValueProp.Unpowered).
#[test]
fn fortifier_ignores_frail_per_csharp_unpowered_prop() {
    use sts2_core::PowerUid;
    ensure_installed();
    let mut state = fresh_state_with_player(50, 80);
    state.player.block = 10;
    let puid = PowerUid::new(1).expect("nz");
    state.powers.push(sts2_core::Power {
        id: puid.0,
        kind: PowerKind::Frail,
        amount: 2,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    let player_uid = state.player.creature_uid.expect("set");
    state
        .creatures
        .iter_mut()
        .find(|c| c.id == player_uid.0)
        .expect("player creature row")
        .powers
        .push(puid);
    assert_eq!(
        dispatch(&mut state, PotionKind::Fortifier, None),
        EffectResult::Resolved
    );
    assert_eq!(
        state.player.block, 30,
        "Frail does not fold the 20 grant (would be 10 + 15 = 25 if it folded)"
    );
}

/// Bead `sts2-rs-jpq2s`: Frail must NOT fold into Ship-in-a-Bottle's
/// 10-block grant (C# BlockVar(10m, Unpowered)).
#[test]
fn ship_in_a_bottle_ignores_frail_per_csharp_unpowered_prop() {
    use sts2_core::PowerUid;
    ensure_installed();
    let mut state = fresh_state_with_player(50, 80);
    let puid = PowerUid::new(1).expect("nz");
    state.powers.push(sts2_core::Power {
        id: puid.0,
        kind: PowerKind::Frail,
        amount: 2,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    let player_uid = state.player.creature_uid.expect("set");
    state
        .creatures
        .iter_mut()
        .find(|c| c.id == player_uid.0)
        .expect("player creature row")
        .powers
        .push(puid);
    assert_eq!(
        dispatch(&mut state, PotionKind::ShipInABottle, None),
        EffectResult::Resolved
    );
    assert_eq!(
        state.player.block, 10,
        "Unpowered 10-block grant ignores Frail (would be 7 if it folded)"
    );
    // BlockNextTurn power applied to player.
    let player_uid = state.player.creature_uid.expect("set");
    let bnt = state
        .creatures
        .iter()
        .find(|c| c.id == player_uid.0)
        .unwrap()
        .powers
        .iter()
        .filter_map(|uid| state.powers.get_by_id(uid.0))
        .find(|p| p.kind == PowerKind::BlockNextTurn)
        .map(|p| p.amount);
    assert_eq!(bnt, Some(10), "BlockNextTurn power applied at 10 stacks");
}

