fn push_enemy(state: &mut CombatState, raw_id: u32, hp: i32) -> sts2_core::CreatureUid {
    use smallvec::SmallVec;
    use sts2_core::{Creature, CreatureUid, IntentHistory, MonsterId, MonsterKind};
    let uid = CreatureUid::new(raw_id).expect("non-zero");
    state.creatures.push(Creature {
        id: uid.0,
        current_hp: hp,
        max_hp: hp,
        block: 0,
        powers: SmallVec::new(),
        species: Some(MonsterKind::Nibbit),
        monster_id: MonsterId(""),
        intent: None,
        intent_history: IntentHistory::default(),
        ai: None,
    });
    state.enemy_uids.push(uid);
    uid
}

fn power_amount_on(state: &CombatState, uid: sts2_core::CreatureUid, kind: PowerKind) -> i32 {
    state
        .creatures
        .iter()
        .find(|c| c.id == uid.0)
        .unwrap()
        .powers
        .iter()
        .filter_map(|p_uid| state.powers.get_by_id(p_uid.0))
        .find(|p| p.kind == kind)
        .map_or(0, |p| p.amount)
}

