#[test]
fn weak_potion_without_target_is_noop() {
    // Direct `dispatch(.., None)` no-ops: the run/combat path
    // (`apply(Action::DrinkPotion)`) resolves a `None` target to the first
    // alive enemy's raw index BEFORE calling the effect, so a `None` only
    // reaches here in degenerate/direct-dispatch callers.
    ensure_installed();
    let mut state = fresh_state_with_player(50, 50);
    let enemy = push_enemy(&mut state, 2, 30);
    assert_eq!(
        dispatch(&mut state, PotionKind::WeakPotion, None),
        EffectResult::Resolved
    );
    assert_eq!(power_amount_on(&state, enemy, PowerKind::Weak), 0);
}

#[test]
fn lethal_drink_potion_ends_combat() {
    // PARITY11 regression (`sts2-rs-potion-lethal-combat-end`): a damage
    // potion that kills the last enemy must end the combat, exactly as a
    // killing-blow card does. `apply(Action::DrinkPotion)` auto-targets the
    // lone enemy (raw index of first alive) and must run `check_combat_end`,
    // setting `is_over` so the run layer transitions to rewards instead of
    // stalling in the play phase (`cs=card_reward rs=combat`).
    use sts2_core::{Action, CombatPhase, StepResult};
    ensure_installed();
    let mut state = fresh_state_with_player(50, 80);
    state.phase = CombatPhase::PlayerPlayPhase;
    let enemy = push_enemy(&mut state, 2, 7); // lone enemy, 7 HP
    state.player.potions.push(PotionKind::PotionShapedRock); // 15 unpowered dmg
    let result = sts2_core::apply(
        &mut state,
        Action::DrinkPotion {
            potion_slot: 0,
            target: None,
        },
    );
    assert!(
        matches!(result, StepResult::CombatWon),
        "lethal drink should resolve combat as won, got {result:?}"
    );
    assert!(
        state.is_over && state.player_won,
        "combat must be over + won"
    );
    let hp = state
        .creatures
        .iter()
        .find(|c| c.id == enemy.0)
        .map_or(0, |c| c.current_hp);
    assert!(hp <= 0, "lone enemy should be dead, hp={hp}");
}

#[test]
fn nonlethal_drink_potion_keeps_combat_open() {
    // Counterpart: a non-lethal drink leaves the enemy alive, so combat
    // continues (no spurious victory from the new combat-end check).
    use sts2_core::{Action, CombatPhase, StepResult};
    ensure_installed();
    let mut state = fresh_state_with_player(50, 80);
    state.phase = CombatPhase::PlayerPlayPhase;
    let enemy = push_enemy(&mut state, 2, 40); // survives 15 dmg
    state.player.potions.push(PotionKind::PotionShapedRock);
    let result = sts2_core::apply(
        &mut state,
        Action::DrinkPotion {
            potion_slot: 0,
            target: None,
        },
    );
    assert!(matches!(result, StepResult::Advanced), "got {result:?}");
    assert!(!state.is_over, "combat must stay open with a live enemy");
    let hp = state
        .creatures
        .iter()
        .find(|c| c.id == enemy.0)
        .map_or(0, |c| c.current_hp);
    assert_eq!(hp, 25, "40 HP enemy takes 15 unpowered damage → 25");
}

#[test]
fn use_potion_alias_forwards_slot_and_target() {
    // GH #303: `Action::UsePotion` used to be a silent no-op stub. It now
    // delegates to `DrinkPotion`, and this is where that delegation can
    // actually be *observed* — sts2-core has no potion bodies installed,
    // so a slot/target mixup is invisible there.
    //
    // Both fields are deliberately set away from their defaults:
    //   * slot 1 of 2, and the two potions differ, so dropping `slot`
    //     (or hardcoding 0) drinks WeakPotion instead of the rock;
    //   * target 1 of 2 alive enemies, so dropping `target` falls into
    //     `DrinkPotion`'s None-defaulting and hits enemy 0 instead.
    // The untargeted enemy is asserted UNHARMED, which is what makes a
    // dropped `target` a failure rather than a coincidence.
    use sts2_core::{Action, CombatPhase, StepResult};
    ensure_installed();
    let mut state = fresh_state_with_player(50, 80);
    state.phase = CombatPhase::PlayerPlayPhase;
    let bystander = push_enemy(&mut state, 2, 40);
    let victim = push_enemy(&mut state, 3, 40);
    state.player.potions.push(PotionKind::WeakPotion);
    state.player.potions.push(PotionKind::PotionShapedRock); // 15 unpowered dmg

    let result = sts2_core::apply(
        &mut state,
        Action::UsePotion {
            slot: 1,
            target: Some(1),
        },
    );
    assert!(matches!(result, StepResult::Advanced), "got {result:?}");

    assert_eq!(
        state.player.potions.as_slice(),
        [PotionKind::WeakPotion],
        "the named slot (1 = the rock) must be the one consumed",
    );
    let hp_of = |uid: sts2_core::CreatureUid| {
        state
            .creatures
            .iter()
            .find(|c| c.id == uid.0)
            .map_or(0, |c| c.current_hp)
    };
    assert_eq!(hp_of(victim), 25, "target enemy 1 takes the 15 damage");
    assert_eq!(
        hp_of(bystander),
        40,
        "enemy 0 must be untouched — a dropped `target` would hit it",
    );
}

