// --- Card-spawn potion tests (bead `sts2-rs-6ynt.9.1`) -----------

fn fresh_state_for_character(character: sts2_core::potions::CharacterId) -> CombatState {
    let mut state = fresh_state_with_player(50, 50);
    state.player.character = Some(character);
    state.rng = sts2_core::dotnet_rng::Rng::new(0_i32);
    // The AddGeneratedFreeToHand resolver materialises the chosen
    // card via the registered card factory; register it so the
    // choose-a-card potion tests can resolve their pending choice.
    sts2_core::register_card_factory(crate::cards::spec_index::card_pod_from_id);
    state
}

/// Resolve the currently-open pending choice by selecting option
/// `idx`. Mirrors the `Action::ResolveChoice` pattern used by the
/// TouchOfInsanity / Ashwater tests.
fn resolve_choice_pick(state: &mut CombatState, idx: u8) {
    let selection: smallvec::SmallVec<[u8; 4]> = [idx].into_iter().collect();
    let res = sts2_core::apply(state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none(), "choice consumed");
}

/// Bead `sts2-rs-91tc1`: AttackPotion opens a generate-3 + choose-1
/// screen; the chosen Attack lands in hand FREE this turn.
#[test]
fn attack_potion_opens_choose_one_of_three_free() {
    use sts2_core::cards::{CardType, VarKey};
    use sts2_core::potions::CharacterId;
    ensure_installed();
    let mut state = fresh_state_for_character(CharacterId::Ironclad);
    let before = state.player.hand.len();
    let before_generated = state.player.generated_cards_this_combat;
    assert_eq!(
        dispatch(&mut state, PotionKind::AttackPotion, None),
        EffectResult::Resolved
    );
    let pc = state.pending_choice.as_ref().expect("choose-a-card opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::AddGeneratedFreeToHand);
    assert_eq!((pc.min_select, pc.max_select), (1, 1), "single pick");
    assert!(pc.can_skip, "C# canSkip: true");
    assert_eq!(pc.options.len(), 3, "GetDistinctForCombat(pool, 3)");
    // No card spawned yet — only the chosen one materialises.
    assert_eq!(state.player.hand.len(), before, "no spawn before resolve");

    resolve_choice_pick(&mut state, 0);
    assert_eq!(
        state.player.hand.len(),
        before + 1,
        "exactly one card in hand after choosing"
    );
    let new_uid = *state.player.hand.last().expect("one new card");
    let spawned = state
        .cards
        .iter()
        .find(|c| c.uid == new_uid)
        .expect("arena");
    assert_eq!(spawned.card_type, CardType::Attack);
    assert!(
        spawned.cost.has(sts2_core::LocalCostMod::FREE_THIS_TURN),
        "chosen card is free this turn (C# SetToFreeThisTurn)"
    );
    assert_eq!(
        state.player.generated_cards_this_combat,
        before_generated + 1
    );
}

/// A drink that both opens a card screen and ends the combat must report the
/// ENDING, not the screen.
///
/// The `DrinkPotion` arm's `pending_choice.is_some() && !state.is_over` guard
/// reads a flag that only `check_combat_end` sets, so with the check running
/// last the guard saw a stale `false` and returned `PendingChoice` on a combat
/// that was already over — leaving `is_over` unset and the run layer parked in
/// the play phase waiting to answer a screen that died with the fight. No
/// shipped potion does both today (`sts2-rs-potion-lethal-combat-end`), so this
/// stages it: an AttackPotion drunk with the lone enemy already at 0 HP.
#[test]
fn a_drink_that_opens_a_screen_and_ends_the_combat_reports_the_ending() {
    use sts2_core::potions::CharacterId;
    use sts2_core::{Action, CombatPhase, StepResult};
    ensure_installed();
    let mut state = fresh_state_for_character(CharacterId::Ironclad);
    state.phase = CombatPhase::PlayerPlayPhase;
    let enemy = push_enemy(&mut state, 2, 40);
    if let Some(c) = state.creatures.iter_mut().find(|c| c.id == enemy.0) {
        c.current_hp = 0;
    }
    state.player.potions.push(PotionKind::AttackPotion);

    let result = sts2_core::apply(
        &mut state,
        Action::DrinkPotion {
            potion_slot: 0,
            target: None,
        },
    );
    assert_eq!(
        result,
        StepResult::CombatWon,
        "the last enemy is dead — the fight is over, screen or no screen",
    );
    assert!(state.is_over, "`is_over` must be set, not left stale");
}

