/// DropletOfPrecognition's selection grid is ordered by `(Rarity, Id)`
/// per C# `DropletOfPrecognition.OnUse` (`orderby c.Rarity, c.Id`), where
/// `c.Id` ties break on the `CardModel.Id.Entry` STRING (ordinal), NOT the
/// `CardId` enum discriminant. The three starters are all `CardRarity.Basic`,
/// so the alphabetical Entry tiebreak puts `BASH` before `STRIKE_IRONCLAD`.
/// Pushing STRIKE then BASH (so a buggy `card_id as u32` sort keeps STRIKE
/// at the head) must still surface BASH as `options[0]`.
#[test]
fn droplet_of_precognition_grid_orders_by_rarity_then_entry_string() {
    use sts2_core::cards::Card;
    use sts2_core::cards::CardId;
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    for (raw, card_id) in [(1u32, CardId::StrikeIronclad), (2u32, CardId::Bash)] {
        let uid = sts2_core::CardUid::new(raw).expect("non-zero card uid");
        state.cards.push(Card {
            uid,
            card_id,
            ..Card::pod_defaults()
        });
        state.player.draw.push(uid);
    }
    assert_eq!(
        dispatch(&mut state, PotionKind::DropletOfPrecognition, None),
        EffectResult::Resolved
    );
    let pc = state.pending_choice.as_ref().expect("draw choice opened");
    // C# ordinal "BASH" < "STRIKE_IRONCLAD" ⇒ BASH heads the grid.
    assert_eq!(
        pc.options[0].card_id,
        CardId::Bash,
        "grid head must be BASH (entry-string tiebreak), not the enum-0 Strike"
    );
}

/// DropletOfPrecognition's grid is rarity-PRIMARY: a Basic card sorts ahead
/// of a Common card regardless of the entry-string tiebreak. C# `orderby
/// c.Rarity, c.Id` with the C# `CardRarity` ordinal (Basic=1 < Common=2).
#[test]
fn droplet_of_precognition_grid_rarity_is_primary() {
    use sts2_core::cards::Card;
    use sts2_core::cards::CardId;
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    // Anger is Common; its entry "ANGER" sorts alphabetically BEFORE "BASH",
    // so an entry-only sort would wrongly head with Anger. Rarity-primary
    // must instead surface the Basic BASH first.
    for (raw, card_id) in [(1u32, CardId::Anger), (2u32, CardId::Bash)] {
        let uid = sts2_core::CardUid::new(raw).expect("non-zero card uid");
        state.cards.push(Card {
            uid,
            card_id,
            ..Card::pod_defaults()
        });
        state.player.draw.push(uid);
    }
    assert_eq!(
        dispatch(&mut state, PotionKind::DropletOfPrecognition, None),
        EffectResult::Resolved
    );
    let pc = state.pending_choice.as_ref().expect("draw choice opened");
    assert_eq!(
        pc.options[0].card_id,
        CardId::Bash,
        "Basic (BASH) must sort ahead of Common (ANGER) — rarity is primary"
    );
}

