/// Bead `sts2-rs-eysmt`: EntropicBrew fills only up to the player's real
/// potion-slot cap (`PlayerCombatState::potion_slots`), NOT the hard
/// `MAX_POTIONS` = 5. C# `EntropicBrew.OnUse` loops
/// `while Owner.HasOpenPotionSlots`, where `HasOpenPotionSlots` is over
/// `_potionSlots` (count == `MaxPotionCount`, default
/// `initialMaxPotionSlotCount == 3`). With a 3-slot cap and 1 potion
/// already held, EntropicBrew adds exactly 2 — leaving the belt at 3, so
/// `legal_actions` surfaces `use_potion` slots 0/1/2 only (never 3/4,
/// the divergence this bead fixes).
#[test]
fn entropic_brew_respects_three_slot_cap() {
    use sts2_core::potions::{CharacterId, PotionKind};
    ensure_installed();
    let mut state = fresh_state_for_character(CharacterId::Ironclad);
    state.player.potion_slots = 3;
    state.player.potions.clear();
    state.player.potions.push(PotionKind::FirePotion);
    assert_eq!(
        dispatch(&mut state, PotionKind::EntropicBrew, None),
        EffectResult::Resolved
    );
    assert_eq!(
        state.player.potions.len(),
        3,
        "EntropicBrew fills only to the 3-slot cap, not MAX_POTIONS=5"
    );

    // The legal-action surface must therefore expose exactly slots 0..3,
    // matching the C# headless harness which enumerates `player.Potions`
    // (a compacted, 3-element list) — never slots 3 or 4. `legal_actions`
    // only enumerates potions in `PlayerPlayPhase`.
    state.phase = sts2_core::CombatPhase::PlayerPlayPhase;
    let drink_slots: Vec<u8> = sts2_core::legal_actions(&state)
        .into_iter()
        .filter_map(|a| match a {
            sts2_core::Action::DrinkPotion { potion_slot, .. } => Some(potion_slot),
            _ => None,
        })
        .collect();
    assert_eq!(
        drink_slots,
        vec![0, 1, 2],
        "use_potion slots must be 0/1/2 only — no phantom 3/4"
    );
}

