/// Bead `sts2-rs-2e9q2` follow-up: Snecko Oil's cost randomization is a
/// per-turn override (C# `EnergyCost.SetThisTurnOrUntilPlayed`), not a
/// permanent rewrite — a card that is NOT played reverts to its base cost
/// at the owner's next turn start (`EndOfTurnCleanup`).
#[test]
fn snecko_oil_cost_randomization_reverts_at_turn_start() {
    use sts2_core::cards::Card;
    ensure_installed();
    let mut state = fresh_state_with_player(50, 50);
    state.rng = sts2_core::dotnet_rng::Rng::new(3_i32);
    // One base-cost-2 card in the draw pile so Snecko draws + randomizes it.
    let mut card = Card::pod_defaults();
    let uid = sts2_core::CardUid::new(1).expect("nz");
    card.uid = uid;
    card.cost = sts2_core::CardEnergyCost::new(2);
    state.cards.push(card);
    state.player.draw.push(uid);

    let _ = dispatch(&mut state, PotionKind::SneckoOil, None);
    let randomized = state
        .cards
        .iter()
        .find(|c| c.uid == uid)
        .unwrap()
        .local_cost();
    assert!(
        (0..=3).contains(&randomized),
        "randomized cost {randomized} out of 0..=3"
    );
    // The base is untouched; the roll is a modifier.
    assert_eq!(state.cards[0].base_cost(), 2);

    // `EndOfTurnCleanup` drops the roll.
    let c = state.cards.iter_mut().find(|c| c.uid == uid).unwrap();
    c.cost.end_of_turn_cleanup();
    assert_eq!(
        c.local_cost(),
        2,
        "Snecko cost reverts to base at the next turn start"
    );
    assert!(!c.cost.has_local_modifiers(), "no modifier left");
}

/// Bead `sts2-rs-0fazg`: SoldiersStew scans Strike-tagged cards
/// across every pile (C# `AllCards` = Hand+Draw+Discard+Exhaust+
/// Play). Stamp a synthetic Strike-tagged Card directly into each
/// of the five piles and confirm the bump reaches all five. (We
/// build the cards by hand with `tags = CardTags::one(Strike)`
/// because `card_pod_from_id`/`card_from_spec` leave Card.tags
/// empty — see the broader tag-plumbing follow-up bead.)
#[test]
fn fazg_soldiers_stew_covers_exhaust_and_play_piles() {
    use sts2_core::cards::{Card, CardTag, CardTags};
    ensure_installed();
    let mut state = fresh_state_with_player(50, 50);
    let mut uids = Vec::new();
    for raw in 1..=5u32 {
        let mut card = Card::pod_defaults();
        let uid = sts2_core::CardUid::new(raw).expect("nz");
        card.uid = uid;
        card.tags = CardTags::one(CardTag::Strike);
        uids.push(uid);
        state.cards.push(card);
    }
    state.player.hand.push(uids[0]);
    state.player.draw.push(uids[1]);
    state.player.discard.push(uids[2]);
    state.player.exhaust.push(uids[3]);
    state.player.play.push(uids[4]);

    assert_eq!(
        dispatch(&mut state, PotionKind::SoldiersStew, None),
        EffectResult::Resolved
    );

    for (label, uid) in [
        ("hand", uids[0]),
        ("draw", uids[1]),
        ("discard", uids[2]),
        ("exhaust", uids[3]),
        ("play", uids[4]),
    ] {
        let card = state
            .cards
            .iter()
            .find(|c| c.uid == uid)
            .expect("card present");
        assert_eq!(
            card.base_replay_count, 1,
            "{label} pile Strike must get +1 base_replay_count"
        );
    }
}

