// ── sts2-rs-6ynt.9.3 — c-uncommon-misc body tests ────────────────

/// Push a `Card` with the given uid + cost + upgraded flag into
/// `state.cards`, returning its [`sts2_core::CardUid`]. Caller is
/// responsible for pushing the uid into the appropriate pile
/// (`state.player.hand` / `discard` / etc.).
fn push_test_card(
    state: &mut CombatState,
    uid_raw: u32,
    cost: i8,
    upgraded: bool,
) -> sts2_core::CardUid {
    use sts2_core::cards::Card;
    let uid = sts2_core::CardUid::new(uid_raw).expect("non-zero card uid");
    state.cards.push(Card {
        uid,
        cost: sts2_core::CardEnergyCost::new(cost),
        upgraded,
        ..Card::pod_defaults()
    });
    uid
}

