/// Bead `sts2-rs-1xmxp`: with 2+ cost-bearing cards, TouchOfInsanity
/// opens a single-pick `MakeFreeInHand` choice (the free card is not
/// a candidate); resolving sets the chosen card's cost to 0.
#[test]
fn touch_of_insanity_opens_make_free_choice_then_resolves() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    let c1 = push_test_card(&mut state, 1, 1, false);
    let c2 = push_test_card(&mut state, 2, 2, false);
    let free = push_test_card(&mut state, 3, 0, false);
    for uid in [c1, c2, free] {
        state.player.hand.push(uid);
    }

    assert_eq!(
        dispatch(&mut state, PotionKind::TouchOfInsanity, None),
        EffectResult::Resolved
    );
    let pc = state
        .pending_choice
        .as_ref()
        .expect("make-free choice opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::MakeFreeInHand);
    assert_eq!((pc.min_select, pc.max_select), (1, 1), "single pick");
    assert_eq!(pc.options.len(), 2, "only the 2 cost-bearing cards");
    let offered: Vec<_> = pc.options.iter().filter_map(|o| o.card_uid).collect();
    assert!(!offered.contains(&free), "free card is not a candidate");
    // Nothing zeroed until resolved.
    let idx1 = c1.0.get() as usize - 1;
    assert_eq!(state.cards[idx1].local_cost(), 1);

    // Resolve: make the first candidate (c1) free.
    let selection: smallvec::SmallVec<[u8; 4]> = [0u8].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none());
    let chosen = offered[0];
    let chosen_idx = chosen.0.get() as usize - 1;
    assert_eq!(
        state.cards[chosen_idx].local_cost(),
        0,
        "chosen card now free"
    );
    // The other candidate is unchanged.
    let other = if chosen == c1 { c2 } else { c1 };
    let other_idx = other.0.get() as usize - 1;
    assert!(
        state.cards[other_idx].local_cost() > 0,
        "unchosen candidate unchanged"
    );
}

