#[test]
fn bottled_potential_reshuffles_hand_into_draw_and_draws_five() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    // Hand: 3 cards. Draw: 5 cards. After potion: hand is 5 cards
    // (out of 3+5=8 available), draw pile has the remaining 3.
    let hand_cards: Vec<_> = (100..103)
        .map(|i| push_test_card(&mut state, i, 1, false))
        .collect();
    for uid in &hand_cards {
        state.player.hand.push(*uid);
    }
    let draw_cards: Vec<_> = (200..205)
        .map(|i| push_test_card(&mut state, i, 1, false))
        .collect();
    for uid in &draw_cards {
        state.player.draw.push(*uid);
    }
    assert_eq!(
        dispatch(&mut state, PotionKind::BottledPotential, None),
        EffectResult::Resolved
    );
    assert_eq!(
        state.player.hand.len(),
        5,
        "BottledPotential should leave exactly 5 cards in hand"
    );
    assert_eq!(
        state.player.draw.len(),
        3,
        "Remaining 8 - 5 drawn = 3 cards should sit in the draw pile",
    );
    // Conservation: every card is accounted for and no duplicates.
    let mut all_uids: Vec<_> = state
        .player
        .hand
        .iter()
        .chain(state.player.draw.iter())
        .copied()
        .collect();
    all_uids.sort();
    all_uids.dedup();
    assert_eq!(all_uids.len(), hand_cards.len() + draw_cards.len());
}

/// Bead `sts2-rs-gpsvo`: with 2+ discard cards, LiquidMemories opens a
/// single-pick `AddFromDiscardFree` choice in DISCARD-PILE ORDER and
/// draws ZERO RNG (C# `FromSimpleGrid` is a pure player choice —
/// LiquidMemories.cs:25-30). Resolving moves the chosen card to hand,
/// stamps `FREE_THIS_TURN`, and zeroes its effective cost this turn.
#[test]
fn liquid_memories_opens_discard_choice_no_rng_then_resolves_free_this_turn() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    let d1 = push_test_card(&mut state, 100, 2, false);
    let d2 = push_test_card(&mut state, 101, 3, false);
    for uid in [d1, d2] {
        state.player.discard.push(uid);
    }
    let rng_before = state.rng.counter();

    assert_eq!(
        dispatch(&mut state, PotionKind::LiquidMemories, None),
        EffectResult::Resolved
    );
    // The fix: a pure player choice consumes NO RNG (the prior port rolled
    // `next_int_exclusive`, desyncing every downstream draw).
    assert_eq!(
        state.rng.counter(),
        rng_before,
        "LiquidMemories must NOT advance the RNG (C# FromSimpleGrid draws nothing)"
    );
    let pc = state
        .pending_choice
        .as_ref()
        .expect("discard-pick choice opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::AddFromDiscardFree);
    assert_eq!((pc.min_select, pc.max_select), (1, 1), "single pick");
    assert_eq!(pc.options.len(), 2, "both discard cards offered");
    // Pile order, NO sort (C# passes `…Cards` with no OrderBy).
    assert_eq!(
        pc.options[0].card_uid,
        Some(d1),
        "options must be in discard-pile order"
    );
    assert_eq!(pc.options[1].card_uid, Some(d2));
    // Nothing moved until resolved.
    assert_eq!(state.player.discard.len(), 2);
    assert!(state.player.hand.is_empty());

    // Resolve: select option 0 (d1).
    let selection: smallvec::SmallVec<[u8; 4]> = [0u8].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none());

    assert!(
        !state.player.discard.contains(&d1),
        "chosen card removed from discard"
    );
    assert!(state.player.hand.contains(&d1), "chosen card now in hand");
    assert!(
        state.player.discard.contains(&d2),
        "unchosen card stays in discard"
    );
    // C# `SetToFreeThisTurn()` is a TEMPORARY override, not a base-cost
    // mutation: the card keeps its base cost (2) but carries FREE_THIS_TURN
    // so its effective cost is 0 this turn / until played.
    let c = state.cards.iter().find(|c| c.uid == d1).expect("card");
    assert_eq!(
        c.base_cost(),
        2,
        "base cost preserved (not permanently zeroed)"
    );
    assert!(
        c.cost.has(sts2_core::LocalCostMod::FREE_THIS_TURN),
        "chosen card flagged FREE_THIS_TURN"
    );
    assert_eq!(
        sts2_core::hooks::effective_card_cost(&state, d1),
        0,
        "effective cost is 0 this turn"
    );
}

