// ── d-rare-combat potion body tests — bead `sts2-rs-6ynt.9.4` ────
//
// The `push_enemy` test helper (3-arg form: state, raw_id, hp) is
// defined further up in this module by the c-uncommon-misc 9.3
// wave and reused here. `fresh_state_with_player` already created
// a creature row at uid=1, so test-local enemies start at uid=2.

/// ShacklingPotion: every alive enemy gains ShacklingPotion x7.
/// Dead enemies (current_hp <= 0) are skipped by the alive filter.
#[test]
fn shackling_potion_applies_seven_to_all_alive_enemies() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    let alive_a = push_enemy(&mut state, 2, 50);
    let alive_b = push_enemy(&mut state, 3, 30);
    let dead = push_enemy(&mut state, 4, 50);
    if let Some(c) = state.creatures.iter_mut().find(|c| c.id == dead.0) {
        c.current_hp = 0;
    }
    assert_eq!(
        dispatch(&mut state, PotionKind::ShacklingPotion, None),
        EffectResult::Resolved
    );
    assert_eq!(
        power_amount_on(&state, alive_a, PowerKind::ShacklingPotion),
        7
    );
    assert_eq!(
        power_amount_on(&state, alive_b, PowerKind::ShacklingPotion),
        7
    );
    assert_eq!(
        power_amount_on(&state, dead, PowerKind::ShacklingPotion),
        0,
        "dead enemies must not receive Shackle"
    );
    // zt05u: TemporaryStrengthPower (IsPositive=false) also folds
    // -7 Strength onto each affected enemy via BeforeApplied.
    assert_eq!(power_amount_on(&state, alive_a, PowerKind::Strength), -7);
    assert_eq!(power_amount_on(&state, alive_b, PowerKind::Strength), -7);
    assert_eq!(
        power_amount_on(&state, dead, PowerKind::Strength),
        0,
        "dead enemies must not receive Strength debuff"
    );
}

/// Loadout Necrobinder 1189 v0.111.0 act2: `TemporaryStrengthPower.BeforeApplied`
/// drains the Strength BEFORE ShacklingPotionPower lands (PowerCmd.cs:132-135),
/// and Sleight of Flesh reacts to that drain. When it kills the target (a
/// Parafright Illusion, which keeps its buffs while reviving), C#'s
/// `if (target.CanReceivePowers)` drops the ShacklingPotionPower itself: the
/// corpse carries Strength -7 only. Rust applied the power first.
#[test]
fn shackling_potion_target_killed_by_its_strength_drain_gets_no_power() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    let player = state.player.creature_uid.expect("player");
    let illusion = push_enemy(&mut state, 2, 6);
    let survivor = push_enemy(&mut state, 3, 50);
    for (raw, uid, kind, amount) in [
        (900, player, PowerKind::SleightOfFlesh, 9),
        (901, illusion, PowerKind::Illusion, 1),
    ] {
        let pid = std::num::NonZeroU32::new(raw).expect("nz");
        state.powers.push(sts2_core::Power::new(pid, kind, amount));
        state
            .creatures
            .iter_mut()
            .find(|c| c.id == uid.0)
            .expect("creature")
            .powers
            .push(sts2_core::PowerUid(pid));
    }
    assert_eq!(
        dispatch(&mut state, PotionKind::ShacklingPotion, None),
        EffectResult::Resolved
    );
    let hp = |uid: sts2_core::CreatureUid| {
        state
            .creatures
            .iter()
            .find(|c| c.id == uid.0)
            .expect("creature")
            .current_hp
    };
    assert_eq!(hp(illusion), 0, "Sleight of Flesh 9 kills the 6-HP target");
    assert_eq!(
        power_amount_on(&state, illusion, PowerKind::ShacklingPotion),
        0,
        "the drain killed it before the power could land"
    );
    assert_eq!(hp(survivor), 50 - 9);
    assert_eq!(
        power_amount_on(&state, survivor, PowerKind::ShacklingPotion),
        7
    );
    assert_eq!(power_amount_on(&state, survivor, PowerKind::Strength), -7);
}

