/// CosmicConcoction parity: the 3 generated cards must come from the FULL
/// combat-generatable ColorlessCardPool (C# `GetDistinctForCombat`), NOT the
/// narrow 18-card "modifier" subset. The old port sampled the modifier subset
/// off `combat_card_generation`, which had wrong membership AND wrong read
/// count, desyncing the stream (it could surface ALCHEMIZE, which has
/// `CanBeGeneratedInCombat=false` and is excluded from the legit pool). This
/// is the Cosmic-Concoction tail of bead `sts2-rs-q6bix`. Asserts every
/// generated card id is in [`colorless_combat_generatable_card_ids`] (so never
/// ALCHEMIZE) and is upgraded.
#[test]
fn cosmic_concoction_draws_from_full_combat_pool_not_modifier_subset() {
    use crate::cards::colorless::helpers::colorless_combat_generatable_card_ids;
    use sts2_core::cards::CardId;
    ensure_installed();
    let full_pool: &[CardId] = colorless_combat_generatable_card_ids();
    assert!(
        !full_pool.contains(&CardId::Alchemize),
        "sanity: Alchemize (CanBeGeneratedInCombat=false) must be absent from the pool"
    );
    // Sweep several RNG starting points so the assertion isn't pinned to one
    // shuffle; every generated card must be a legit combat-generatable
    // colorless card.
    for seed in 0i32..16 {
        let mut state = fresh_state_with_player(80, 80);
        state.player.character = Some(sts2_core::CharacterId::Ironclad);
        state.run_rng.combat_card_generation =
            sts2_core::DotNetRng::new(seed.wrapping_mul(2_654_435_761_u32 as i32));
        let hand_before = state.player.hand.len();
        assert_eq!(
            dispatch(&mut state, PotionKind::CosmicConcoction, None),
            EffectResult::Resolved
        );
        for &uid in state.player.hand.iter().skip(hand_before) {
            let idx = uid.0.get() as usize - 1;
            let card = &state.cards[idx];
            assert!(
                full_pool.contains(&card.card_id),
                "seed {seed}: generated {:?} is not in the combat-generatable colorless pool",
                card.card_id
            );
            assert_ne!(
                card.card_id,
                CardId::Alchemize,
                "seed {seed}: must never generate ALCHEMIZE"
            );
            assert!(
                card.upgraded,
                "seed {seed}: generated card must be upgraded"
            );
        }
    }
}

