// ── sts2-rs-bavw / sts2-rs-d5na — Ashwater + GamblersBrew tests ─────

/// Ashwater: a uniform-random subset of the hand is moved into the
/// exhaust pile. With a seeded RNG the count is deterministic; we
/// assert conservation (`hand_delta == exhaust_delta`) rather than a
/// specific count, so the test remains robust if the RNG sample
/// shape evolves. Empty-hand short-circuit is covered implicitly by
/// the registry-install path. Bead `sts2-rs-bavw`.
#[test]
fn ashwater_opens_exhaust_choice_then_resolves() {
    // Bead `sts2-rs-1xmxp`: Ashwater opens an `ExhaustFromHand` player
    // choice (exhaust any number, min 0..hand, skippable) instead of a
    // random subset; resolving exhausts the chosen cards.
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    let in_hand = [
        push_test_card(&mut state, 1, 1, false),
        push_test_card(&mut state, 2, 2, false),
        push_test_card(&mut state, 3, 0, false),
        push_test_card(&mut state, 4, 1, false),
    ];
    for uid in in_hand {
        state.player.hand.push(uid);
    }
    assert_eq!(
        dispatch(&mut state, PotionKind::Ashwater, None),
        EffectResult::Resolved
    );
    // Choice opened over the whole hand; nothing exhausted yet.
    let pc = state
        .pending_choice
        .as_ref()
        .expect("exhaust choice opened");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::ExhaustFromHand);
    assert_eq!(pc.min_select, 0, "exhaust any number incl. zero");
    assert_eq!(pc.max_select as usize, in_hand.len());
    assert!(pc.can_skip, "min 0 → skippable");
    assert!(state.player.exhaust.is_empty(), "no exhaust until resolved");
    assert_eq!(state.player.hand.len(), in_hand.len());

    // Resolve: exhaust the cards at indices 0 and 2.
    let selection: smallvec::SmallVec<[u8; 4]> = [0u8, 2].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none());
    assert_eq!(state.player.exhaust.len(), 2, "2 chosen cards exhausted");
    assert!(state.player.exhaust.contains(&in_hand[0]));
    assert!(state.player.exhaust.contains(&in_hand[2]));
    assert_eq!(state.player.hand.len(), 2, "2 cards remain in hand");
    assert!(state.player.hand.contains(&in_hand[1]));
    assert!(state.player.hand.contains(&in_hand[3]));
}

/// GamblersBrew (bead `sts2-rs-1xmxp`): opens a
/// `DiscardFromHandAndDraw` player choice; resolving discards the
/// chosen cards and draws that many back, so hand size is invariant
/// when the draw pile can satisfy the replenish.
#[test]
fn gamblers_brew_opens_discard_and_draw_choice_then_resolves() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    let hand_cards = [
        push_test_card(&mut state, 1, 1, false),
        push_test_card(&mut state, 2, 2, false),
        push_test_card(&mut state, 3, 0, false),
        push_test_card(&mut state, 4, 1, false),
    ];
    for uid in hand_cards {
        state.player.hand.push(uid);
    }
    let draw_cards: Vec<_> = (5..15u32)
        .map(|i| push_test_card(&mut state, i, 1, false))
        .collect();
    for uid in &draw_cards {
        state.player.draw.push(*uid);
    }
    assert_eq!(
        dispatch(&mut state, PotionKind::GamblersBrew, None),
        EffectResult::Resolved
    );
    // Choice opened over the whole hand; nothing changed yet.
    let pc = state.pending_choice.as_ref().expect("discard+draw choice");
    assert_eq!(pc.kind, sts2_core::ChoiceKind::DiscardFromHandAndDraw);
    assert_eq!(pc.min_select, 0);
    assert_eq!(pc.max_select as usize, hand_cards.len());
    assert!(pc.can_skip);
    assert!(state.player.discard.is_empty());

    // Resolve: discard 2 (indices 0, 1) → draw 2 back.
    let draw_before = state.player.draw.len();
    let selection: smallvec::SmallVec<[u8; 4]> = [0u8, 1].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);
    assert!(state.pending_choice.is_none());
    assert_eq!(state.player.discard.len(), 2, "2 chosen cards discarded");
    assert!(state.player.discard.contains(&hand_cards[0]));
    assert!(state.player.discard.contains(&hand_cards[1]));
    assert_eq!(
        state.player.hand.len(),
        hand_cards.len(),
        "hand invariant: 2 discarded, 2 drawn back",
    );
    assert_eq!(state.player.draw.len(), draw_before - 2, "drew 2 from draw");
}

/// GamblersBrew (bead `sts2-rs-9sgbe`): each chosen card is an *active*
/// discard, so resolving fires `after_card_discarded` once per discarded
/// card — exactly as C# `CardCmd.DiscardAndDraw` calls
/// `Hook.AfterCardDiscarded` inside its per-card loop
/// (`MegaCrit.Sts2.Core.Commands/CardCmd.cs:150`). We pin the hook fire
/// via the per-turn discard counter the single dispatch site bumps
/// (`hooks::dispatch_after_card_discarded`); a raw pile move (the prior
/// buggy port) would leave the counter at zero. The draw happens AFTER
/// every discard (CardCmd.cs:153-156).
#[test]
fn gamblers_brew_active_discard_fires_after_card_discarded_per_card() {
    ensure_installed();
    let mut state = fresh_state_with_player(80, 80);
    let hand_cards = [
        push_test_card(&mut state, 1, 1, false),
        push_test_card(&mut state, 2, 2, false),
        push_test_card(&mut state, 3, 0, false),
    ];
    for uid in hand_cards {
        state.player.hand.push(uid);
    }
    // Plenty of draw so the post-discard replenish never reshuffles.
    for i in 5..15u32 {
        let uid = push_test_card(&mut state, i, 1, false);
        state.player.draw.push(uid);
    }
    // Discard counter starts clean for this turn.
    state.combat_log.cards_discarded_this_turn = 0;
    let cards_drawn_before = state.cards_drawn;

    assert_eq!(
        dispatch(&mut state, PotionKind::GamblersBrew, None),
        EffectResult::Resolved
    );
    // Resolve: discard the 3 cards at indices 0, 1, 2.
    let selection: smallvec::SmallVec<[u8; 4]> = [0u8, 1, 2].into_iter().collect();
    let res = sts2_core::apply(&mut state, sts2_core::Action::ResolveChoice { selection });
    assert_eq!(res, sts2_core::StepResult::Advanced);

    // The active-discard hook fired once per discarded card (raw move
    // would leave this at 0).
    assert_eq!(
        state.combat_log.cards_discarded_this_turn, 3,
        "after_card_discarded fired once per active discard"
    );
    // Draw replenished one card per discard via the canonical hand-draw
    // site, which bumps the cards-drawn counter (a raw `cards::draw`
    // would not).
    assert_eq!(
        u32::from(state.cards_drawn - cards_drawn_before),
        3,
        "drew one card per discard through the canonical draw site"
    );
    assert_eq!(
        state.player.discard.len(),
        3,
        "all 3 chosen cards discarded"
    );
    assert_eq!(
        state.player.hand.len(),
        hand_cards.len(),
        "hand invariant: 3 discarded, 3 drawn"
    );
}

