#[test]
fn bone_brew_on_living_osty_grows_max_hp() {
    ensure_installed();
    let mut state = CombatState::default();
    assert_eq!(
        dispatch(&mut state, PotionKind::BoneBrew, None),
        EffectResult::Resolved
    );
    let pet_uid = state.player.pet_uid.expect("Osty");
    // Second drink while Osty is alive: max_hp grows by amount.
    assert_eq!(
        dispatch(&mut state, PotionKind::BoneBrew, None),
        EffectResult::Resolved
    );
    let osty = state.creatures.iter().find(|c| c.id == pet_uid.0).unwrap();
    assert_eq!(osty.max_hp, 2 * BONE_BREW_SUMMON_AMOUNT);
    // current_hp clamped to new max_hp via gain_max_hp.
    assert_eq!(osty.current_hp, 2 * BONE_BREW_SUMMON_AMOUNT);
    // DieForYou stack count remains 1 (idempotent).
    let stacks: i32 = osty
        .powers
        .iter()
        .filter_map(|puid| {
            state
                .powers
                .iter()
                .find(|p| p.id == puid.0 && p.kind == PowerKind::DieForYou)
        })
        .map(|p| p.amount)
        .sum();
    assert_eq!(stacks, 1);
}

#[test]
fn bone_brew_revives_dead_osty_to_full_amount() {
    ensure_installed();
    let mut state = CombatState::default();
    let _ = dispatch(&mut state, PotionKind::BoneBrew, None);
    let pet_uid = state.player.pet_uid.unwrap();
    // Kill the Osty in place.
    {
        let osty = state
            .creatures
            .iter_mut()
            .find(|c| c.id == pet_uid.0)
            .unwrap();
        osty.current_hp = 0;
        osty.max_hp = 1;
        osty.block = 3;
    }
    let _ = dispatch(&mut state, PotionKind::BoneBrew, None);
    let osty = state.creatures.iter().find(|c| c.id == pet_uid.0).unwrap();
    assert_eq!(osty.max_hp, BONE_BREW_SUMMON_AMOUNT);
    assert_eq!(osty.current_hp, BONE_BREW_SUMMON_AMOUNT);
    assert_eq!(osty.block, 0, "revive must reset block to 0");
    // Same pet_uid — revive doesn't reallocate the creature row.
    assert_eq!(state.player.pet_uid, Some(pet_uid));
}

