// --- ALCHEMIZE / EntropicBrew belt generation (bead `sts2-rs-jejon`) ----

/// ALCHEMIZE rolls its potion off the `CombatPotionGeneration` stream
/// (2 draws: NextFloat rarity + NextItem pick) and pushes it onto the
/// belt — matching C# `Alchemize.OnPlay → CreateRandomPotionInCombat`.
/// The prior port drew a single uniform `next_int` off the combat-local
/// `state.rng` stream, leaving `combat_potion_generation` untouched.
#[test]
fn alchemize_rolls_off_combat_potion_generation_stream() {
    use sts2_core::potions::CharacterId;
    let mut state = fresh_state_with_player(50, 50);
    state.player.character = Some(CharacterId::Ironclad);

    let cpg_before = state.run_rng.combat_potion_generation.counter();
    let combat_rng_before = state.rng.counter();
    assert!(state.player.potions.is_empty());

    crate::potions::all::alchemize_procure_random_potion(&mut state);

    assert_eq!(state.player.potions.len(), 1, "one potion procured");
    assert_eq!(
        state.run_rng.combat_potion_generation.counter() - cpg_before,
        2,
        "exactly 2 draws off CombatPotionGeneration (rarity float + item int)"
    );
    assert_eq!(
        state.rng.counter(),
        combat_rng_before,
        "combat-local rng stream must NOT be touched"
    );
    // The rolled potion is never a `CanBeGeneratedInCombat => false` one.
    let k = state.player.potions[0];
    assert!(!k.is_event_only(), "{k:?} is event-only / non-combat-gen");
}

/// ALCHEMIZE on a full belt still rolls (C# rolls before discovering the
/// belt is full, so the stream advances) but adds nothing.
#[test]
fn alchemize_full_belt_still_advances_stream() {
    use sts2_core::potions::{CharacterId, MAX_POTIONS};
    let mut state = fresh_state_with_player(50, 50);
    state.player.character = Some(CharacterId::Ironclad);
    for _ in 0..MAX_POTIONS {
        state.player.potions.push(PotionKind::BlockPotion);
    }
    let cpg_before = state.run_rng.combat_potion_generation.counter();
    crate::potions::all::alchemize_procure_random_potion(&mut state);
    assert_eq!(state.player.potions.len(), MAX_POTIONS, "belt unchanged");
    assert_eq!(
        state.run_rng.combat_potion_generation.counter() - cpg_before,
        2,
        "the roll still consumes 2 draws even when the belt is full"
    );
}

/// EntropicBrew fills every empty slot off the `CombatPotionGeneration`
/// stream (2 draws per fill) up to `MAX_POTIONS` — matching C#
/// `EntropicBrew.OnUse → CreateRandomPotionOutOfCombat` looped on
/// `HasOpenPotionSlots`.
#[test]
fn entropic_brew_fills_belt_off_combat_potion_generation() {
    use sts2_core::potions::{CharacterId, MAX_POTIONS};
    let mut state = fresh_state_with_player(50, 50);
    state.player.character = Some(CharacterId::Ironclad);
    // One existing potion → MAX_POTIONS-1 fills.
    state.player.potions.push(PotionKind::BlockPotion);
    let open = MAX_POTIONS - 1;

    let cpg_before = state.run_rng.combat_potion_generation.counter();
    crate::potions::all::entropic_brew_fill_belt(&mut state);

    assert_eq!(state.player.potions.len(), MAX_POTIONS, "belt filled");
    assert_eq!(
        state.run_rng.combat_potion_generation.counter() - cpg_before,
        2 * open as u32,
        "2 draws per filled slot"
    );
}

/// EntropicBrew drunk from slot 0 of [Brew, Energy, _] refills the HOLE
/// first: C# `RemovePotionInternal` nulls the slot without compacting and
/// `AddPotionInternal` takes `_potionSlots.IndexOf(null)` (`Player.cs:640`,
/// `:703-708`), so the result is [roll1, Energy, roll2], not
/// [Energy, roll1, roll2] (GH #1054, Ironclad seed 1004).
#[test]
fn entropic_brew_refills_lowest_open_slot_first() {
    use sts2_core::potions::CharacterId;
    let mut state = fresh_state_with_player(50, 50);
    state.player.character = Some(CharacterId::Ironclad);
    state.player.potion_slots = 3;
    state.player.potions.push(PotionKind::EntropicBrew);
    state.player.potions.push(PotionKind::EnergyPotion);

    // Predict the two rolls off a clone of the stream.
    let mut rng = state.run_rng.combat_potion_generation.clone();
    let r1 = crate::potions::all::create_random_potions_out_of_combat(
        &mut rng,
        CharacterId::Ironclad,
        1,
    )[0];
    let r2 = crate::potions::all::create_random_potions_out_of_combat(
        &mut rng,
        CharacterId::Ironclad,
        1,
    )[0];

    // Drink the Brew from visible slot 0, then fill.
    state.player.remove_potion_at(0);
    crate::potions::all::entropic_brew_fill_belt(&mut state);

    assert_eq!(
        state.player.potions.as_slice(),
        [r1, PotionKind::EnergyPotion, r2].as_slice(),
        "first roll fills the drunk Brew's slot 0, second fills slot 2"
    );
}

/// Give the combat a Sozu relic (the only `ShouldProcurePotion` override).
fn give_sozu(state: &mut CombatState) {
    use std::num::NonZeroU32;
    state.relics.push(sts2_core::Relic {
        id: NonZeroU32::new(1).expect("non-zero"),
        kind: sts2_core::RelicKind::Sozu,
        counter: 0,
        is_wax: false,
        is_melted: false,
    });
}

/// Sozu vetoes ALCHEMIZE's potion, but only after the roll: C#
/// `Alchemize.OnPlay` rolls `CreateRandomPotionInCombat` first, then
/// `PotionCmd.TryToProcure` fails `NotAllowed` (`PotionCmd.cs:31`,
/// `Sozu.cs:17`). The stream still advances by 2.
#[test]
fn alchemize_vetoed_by_sozu_still_rolls() {
    use sts2_core::potions::CharacterId;
    let mut state = fresh_state_with_player(50, 50);
    state.player.character = Some(CharacterId::Ironclad);
    give_sozu(&mut state);
    let cpg_before = state.run_rng.combat_potion_generation.counter();
    crate::potions::all::alchemize_procure_random_potion(&mut state);
    assert!(state.player.potions.is_empty(), "Sozu blocks the procure");
    assert_eq!(
        state.run_rng.combat_potion_generation.counter() - cpg_before,
        2
    );
}

/// Sozu stops EntropicBrew after ONE roll: `EntropicBrew.OnUse` rolls, then
/// `TryToProcure` fails `NotAllowed` and the loop breaks
/// (`EntropicBrew.cs:24-29`). DelicateFrond runs the same loop; on Ironclad
/// seed 2170 (v0.111.0) Rust filled 3 slots with 6 draws where C# drew 2.
#[test]
fn entropic_brew_vetoed_by_sozu_rolls_once_and_adds_nothing() {
    use sts2_core::potions::CharacterId;
    let mut state = fresh_state_with_player(50, 50);
    state.player.character = Some(CharacterId::Ironclad);
    state.player.potion_slots = 3;
    give_sozu(&mut state);
    let cpg_before = state.run_rng.combat_potion_generation.counter();
    crate::potions::all::entropic_brew_fill_belt(&mut state);
    assert!(state.player.potions.is_empty(), "Sozu blocks every procure");
    assert_eq!(
        state.run_rng.combat_potion_generation.counter() - cpg_before,
        2,
        "one roll, then the vetoed procure breaks the loop"
    );
}

/// Every generate-and-choose screen that makes its pick free (Splash,
/// Discovery, Abundance, the Attack/Skill/Power/Colorless potions) calls
/// `SetToFreeThisTurn()` BEFORE `AddGeneratedCardToCombat` (`Splash.cs`,
/// `Discovery.cs`, `AttackPotion.cs`, ...). So a picked Stomp's
/// `AfterCardEnteredCombat` shave (`AddThisTurn(-attacks)`, `Stomp.cs`) folds
/// AFTER the local zero: the local cost goes below 0, and
/// `Hook.ModifyEnergyCostInCombat` returns a negative cost untouched, so
/// Borrowed Time's +2 never lands. Pushing the zero after the shave left the
/// local cost at 0 and the card at 2 (loadout Necrobinder 7931 v0.107.1:
/// Splash picked a Stomp, C# 0, Rust 2).
#[test]
fn free_generated_pick_is_free_before_it_enters_combat() {
    use sts2_core::cards::{CardId, CardType};
    ensure_installed();
    let mut state = fresh_state_for_character(CharacterId::Necrobinder);
    let pid = std::num::NonZeroU32::new(1).expect("nz");
    state.powers.push(sts2_core::Power {
        id: pid,
        kind: sts2_core::PowerKind::BorrowedTime,
        amount: 2,
        counter: 0,
        applier: None,
        skip_next_tick: false,
    });
    state.player.powers.push(sts2_core::PowerUid(pid));
    state.player.cards_played_this_turn[CardType::Attack.index()] = 1;
    state.request_card_choice(
        sts2_core::ChoiceKind::AddGeneratedFreeToHand,
        vec![sts2_core::ChoiceOption {
            card_id: CardId::Stomp,
            upgraded: true,
            card_uid: None,
            source_pile: None,
        }],
        1,
        1,
        true,
    );

    resolve_choice_pick(&mut state, 0);

    let uid = *state.player.hand.last().expect("the pick is in hand");
    let stomp = &state.cards[uid.0.get() as usize - 1];
    assert_eq!(stomp.card_id, CardId::Stomp);
    assert_eq!(stomp.local_cost(), -1, "0, then the -1 shave");
    assert_eq!(
        sts2_core::hooks::effective_card_cost(&state, uid),
        0,
        "a negative local cost skips Borrowed Time"
    );
}
